/* v1.1 F01 speaking design fixture. Source: content/speaking.json,
 * app/learn/speaking.tsx:14-38, app/study-app.tsx:60/99/107/115.
 * No microphone, audio API, downloads, network, or persistent storage.
 * Include after design.js. Root render must merge window.designExtras.
 */
(function () {
  const photo = 'data:image/webp;base64,';
  const tasks = [
    {id:'speaking-read-01',type:'read-aloud',label:'朗读',title:'图书馆通知',prep:45,answer:45,
      prompt:'Read the announcement aloud. Aim for clear phrasing and a steady pace.',
      passage:'Attention, library visitors. Starting next Monday, our second-floor reading room will open at eight in the morning, one hour earlier than usual. This change will give students and other visitors more quiet study time. Please remember that food is not permitted in the reading room. Drinks in containers with lids are welcome. If you need assistance, speak to a member of staff at the front desk.',
      guide:['先用准备时间找到长句的停顿位置。','读清地点、日期和服务变化，不需要刻意模仿口音。','录音后只选一处重音或停顿重新练习。'],
      sample:'Attention, library visitors. Starting next Monday, our second-floor reading room will open at eight in the morning, one hour earlier than usual. This change will give students and other visitors more quiet study time. Please remember that food is not permitted in the reading room. Drinks in containers with lids are welcome. If you need assistance, speak to a member of staff at the front desk.',summary:'清楚读出通知，留意长句停顿。'},
    {id:'speaking-picture-01',type:'describe-picture',label:'图片描述',title:'一次小组会议',prep:45,answer:30,photo:true,
      prompt:'Describe the photograph in as much detail as you can.',
      guide:['先说场景，再说主要人物及动作。','用 standing、seated、holding 和 on the table 描述可见信息。','描述看得到的内容；不必猜测人物身份或公司。'],
      sample:'This picture shows a small meeting in an office. A woman is standing beside a whiteboard and holding a marker. Two other people are seated at a table. There is a closed laptop on the table, and I can also see cups. The people appear to be discussing something together.',summary:'从场景、人物与动作说起。'},
    {id:'speaking-respond-01',type:'respond',label:'简短问答',title:'你的学习时间',prep:3,answer:15,
      prompt:'When do you usually study English, and where do you study?',
      guide:['回答时间和地点两个信息点。','两句简单完整的话就够。','这是问答类中 15 秒小题的练习，并非完整三题组。'],
      sample:'I usually study English after dinner. I study at the desk in my bedroom because it is quiet and I can concentrate there.',summary:'回答时间与地点；这是单题专项。'},
    {id:'speaking-information-01',type:'use-information',label:'资料回答',title:'查询培训安排',prep:45,answer:15,
      prompt:'I would like to attend the email-writing session. What time does it start, and who is the presenter?',
      passage:'Customer Support Workshop — Friday, October 9\n9:00–9:30 Registration\n9:30–10:45 Writing clear email replies — Nina Brooks\n10:45–11:00 Break\n11:00–12:00 Handling customer complaints — Omar Chen',
      guide:['先阅读日程，定位课程、开始时间和讲师。','用完整句答出 9:30 和 Nina Brooks 两个信息点。','本练习的 45 秒用于阅读资料；正式考试每个问题后另有 3 秒间隔，完整该类含三题。'],
      sample:'The email-writing session starts at nine thirty in the morning. The presenter is Nina Brooks.',summary:'先读日程，再定位时间与讲师。'},
    {id:'speaking-opinion-01',type:'express-opinion',label:'表达观点',title:'每天短练还是周末长练',prep:45,answer:60,
      prompt:'Some people prefer to study a language for a short time every day. Others prefer one long study session each week. Which do you prefer, and why?',
      guide:['用一句话明确选择。','给出两个理由，每个理由配一个具体细节。','优先做到观点清晰、内容相关、不断句；无需塞入高级词。'],
      sample:'I prefer to study for a short time every day. First, it is easier to fit a short lesson into my schedule. For example, I can practice listening for ten minutes after dinner, even on a busy day. Second, daily practice helps me remember new expressions. If I learn a phrase on Monday and use it again on Tuesday, it becomes more familiar. A long weekly session can be useful for a practice test, but I may feel tired and lose concentration. For these reasons, I would choose short daily lessons and add an occasional longer session when I have more time.',summary:'明确选择，用两个具体理由支持。'}
  ];
  let taskId = tasks.some(t=>t.id===params.get('task')) ? params.get('task') : 'speaking-read-01';
  let checks = new Set();
  let playing = false;
  let sampleOpen = false;
  let samplePlaying = false;
  let downloaded = false;
  let requestReturn = false;
  let returnTarget = 'speakinglist';
  let catalogScroll = 0;
  let checkinLoad = '刚好';
  let checkinNote = '';
  let checkinMinutes = 2;
  let saveTimer;
  let historyPlaying = false;
  let selectedHistory = 'speaking-picture-01';
  let previousFixtureState = '';
  const nativeFixture = params.get('runtime') === 'native';
  const task = () => tasks.find(t=>t.id===taskId) || tasks[0];
  const esc = value => escapeHTML(String(value));
  const action = (label,id,primary=false,extra='') => btn(label,null,primary,`data-speaking-action="${id}" ${extra}`);
  const minsec = n => `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
  const savedStates = new Set(['saved','self','checkin','checkin-error','checkin-saved']);
  const audioStates = new Set(['saving','save-error','saved','self','discard','exit-saving','interrupted']);
  function normalizedState() {
    if(state==='picture')taskId='speaking-picture-01';
    if(state==='information')taskId='speaking-information-01';
    if(state==='respond')taskId='speaking-respond-01';
    if(state==='opinion')taskId='speaking-opinion-01';
    if(state==='self'&&previousFixtureState!=='self')checks.add(0);
    previousFixtureState=state;
    return ['picture','information','respond','opinion'].includes(state)?'default':state;
  }
  function setState(next,focus) {
    state=next;
    render();
    if(focus)requestAnimationFrame(()=>document.querySelector(focus)?.focus({preventScroll:true}));
  }
  function noThemeHead(title,sub) {
    return `<div class="pagehead sp-pagehead"><div><div class="eyebrow">口语专项</div><h1>${title}</h1><p>${sub}</p></div></div>`;
  }
  function toolbar() {
    return `<div class="sp-toolbar">${action('← 返回口语目录','return')}<span>原创专项 · 练习与自评</span>${action('历史录音','history')}</div>`;
  }
  function material(t) {
    return `<section class="sp-material panel" aria-labelledby="sp-material-title"><div class="sp-sectionhead"><h2 id="sp-material-title">${t.photo?'题目图片':t.passage?'练习材料':'练习问题'}</h2><span>${t.label}</span></div>${t.photo?`<figure class="sp-photo"><img src="${photo}" width="960" height="640" alt="小组在办公室开会：一人站在白板旁，两人坐在桌边"/><figcaption>题目图片 · 原创练习素材</figcaption></figure>`:''}<p class="sp-prompt" lang="en">${esc(t.prompt)}</p>${t.passage?`<div class="sp-passage" lang="en">${esc(t.passage)}</div>`:''}<details class="sp-guide"><summary>练习提示</summary><ul>${t.guide.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></details></section>`;
  }
  function player(label='本次录音',history=false) {
    const p=history?historyPlaying:playing;
    const duration=history?(selectedHistory==='speaking-read-01'?45:28):Math.min(task().answer,28);
    return `<div class="sp-player" role="group" aria-label="${label}"><div class="sp-player-row">${action(p?'暂停':'播放',history?'history-play':'play',false,`aria-pressed="${p}" aria-label="${p?'暂停':'播放'}${label}"`)}<div><strong>${label}</strong><span>${p?'回听中 · 静音演示':'可回听 · 静音演示'}</span></div><span class="sp-time">${p?'00:11':'00:00'} / ${minsec(duration)}</span></div><div class="sp-audio-track" aria-hidden="true"><i style="width:${p?39:0}%"></i></div></div>`;
  }
  function reflect(t,s) {
    return `<div class="sp-reflect"><h2>回听，只改一个地方</h2><p class="sp-secondary">按真实感受自评，不产生自动分数。</p><fieldset class="sp-checks"><legend>这一次我留意了</legend>${t.guide.map((g,i)=>`<label><input type="checkbox" data-speaking-check="${i}" ${checks.has(i)?'checked':''}/><span>${esc(g)}</span></label>`).join('')}</fieldset><details class="sp-sample" ${sampleOpen?'open':''}><summary data-speaking-summary>看看一种表达方式</summary><p lang="en">${esc(t.sample)}</p>${action(samplePlaying?'暂停示范':'听示范表达','sample-audio',false,`aria-pressed="${samplePlaying}"`)}</details><div class="sp-final-actions">${action('再说一次','rerecord',false,s==='save-error'||s==='saving'||s==='exit-saving'||s==='discard'||s==='interrupted'?'disabled':'')}${action('记录收获','checkin',true,s==='save-error'||s==='saving'||s==='exit-saving'||s==='discard'||s==='interrupted'?'disabled':'')}</div>${!savedStates.has(s)?'<p class="sp-secondary">录音保存成功后，才能再录或记录收获。</p>':''}<p class="sp-contract">自评勾选只用于本轮回听；学习时间与手记在下一步单独确认。</p></div>`;
  }
  function recordPanel(t,s) {
    const audio=audioStates.has(s);
    const prep=s==='prep';
    const recording=s==='recording';
    const pending=['processing','exit-recording'].includes(s);
    const saving=['saving','exit-saving'].includes(s);
    const failed=['save-error','discard','interrupted'].includes(s);
    const ready=['default','permission','unsupported'].includes(s);
    const seconds=recording?Math.min(18,t.answer):prep?Math.min(32,t.prep):t.prep;
    let phaseName = ready?'秒准备':prep?'准备剩余':recording?'回答剩余':pending?'整理录音':saving?'保存中':failed?'待保存':'已保存';
    let content = `<aside class="sp-control panel"><div class="sp-sectionhead"><h2>${audio?'回听与自评':'准备与录音'}</h2><span>${phaseName}</span></div>`;
    if(!audio)content += `<div class="sp-timer ${recording?'sp-is-recording':''}"><b>${pending?'…':minsec(seconds)}</b><span>${phaseName}</span></div><div class="sp-durations"><span>准备 <strong>${t.prep} 秒</strong></span><span>回答 <strong>${t.answer} 秒</strong></span></div>`;
    if(ready)content += `${s==='permission'?'<div class="notice error" role="alert"><strong>麦克风未获允许</strong><p>在浏览器或手机设置中允许使用麦克风，再重新准备。尚未生成录音。</p></div>':''}${s==='unsupported'?'<div class="notice error" role="alert"><strong>当前设备无法录音</strong><p>先检查系统录音支持；网页版可使用支持录音的浏览器。不会显示已保存。</p></div>':''}<p class="sp-secondary">点击后请求麦克风。准备结束会自动开始录音；也可以提前开始。</p><div class="sp-stack">${action(s==='permission'?'重新准备':'开始准备','prepare',true)}</div>`;
    if(prep)content += `<div class="notice" role="status">准备倒计时结束后自动开始录音。</div><div class="sp-stack">${action('准备好了，开始录音','record',true)}${action('取消准备','cancel-prep')}</div>`;
    if(recording)content += `<div class="sp-recording-label" role="status"><i aria-hidden="true"></i>正在录音</div><p class="sp-secondary">时间到自动结束。也可以提前停录。</p><div class="sp-stack">${action('结束录音','stop',true)}</div>`;
    if(pending)content += `<div class="notice" role="status"><strong>${s==='exit-recording'?'已结束录音，正在整理':'正在整理已录内容'}</strong><p>${s==='exit-recording'?'返回请求已收到。整理和保存完成前留在本页。':'整理结束后，会尝试保存在本机。'}</p></div><div class="sp-stack">${action('正在整理…','wait',true,'disabled')}</div>`;
    if(audio)content += player();
    if(saving)content += `<div class="notice" role="status"><strong>正在保存录音…</strong><p>${s==='exit-saving'?'暂时不能离开。保存完成后，再返回目录；失败时可重试或下载保留。':'可以先回听。保存成功后，再录与记录收获会恢复可用。'}</p></div>`;
    if(failed)content += `<div class="notice error" role="alert"><strong>${s==='interrupted'?'录音已中断，保存未完成':'录音尚未保存'}</strong><p>这段音频仍留在当前页面，可回听、重试或下载保留。离开页面可能丢失未保存音频。</p></div><div class="sp-recovery">${action('重试保存','retry',true)}${action('下载保留录音','download')}${action('放弃并离开','discard',false,'class="sp-danger-link"')}</div>${downloaded?'<p class="sp-secondary" role="status">下载入口已演示。实际操作需确认文件确已保留；下载不等于存入学习记录。</p>':''}`;
    if(savedStates.has(s))content += `<div class="notice sp-saved" role="status"><strong>录音已保存在本机</strong><p>${nativeFixture?'保存在这台设备。':'待联网同步；本机副本已保留。'}</p></div>`;
    if(audio)content += `<dl class="sp-meta"><div><dt>练习开始</dt><dd>10 月 13 日 19:42</dd></div><div><dt>录音长度</dt><dd>${Math.min(t.answer,28)} 秒</dd></div></dl>${reflect(t,s)}`;
    content += '</aside>';
    return content;
  }
  function discardModal() {
    return `<div class="modal-cover sp-modal-cover"><section class="modal sp-dialog" role="dialog" aria-modal="true" aria-labelledby="sp-discard-title" aria-describedby="sp-discard-description"><h2 id="sp-discard-title">放弃这段未保存录音？</h2><p id="sp-discard-description">录音未保存到学习记录。离开会释放本页的临时音频，之后可能无法找回。可先重试保存，或下载并确认文件已保留。</p><div class="sp-stack">${action('留在这里','stay',true)}${action('重试保存','retry')}${action('下载保留录音','download')}${action('确认放弃并离开','confirm-discard',false,'class="sp-danger-link"')}</div></section></div>`;
  }
  function checkinPanel(s) {
    return `<section class="sp-checkin panel"><h2>${s==='checkin-saved'?'收获已记录':'记录这次收获'}</h2>${s==='checkin-saved'?`<div class="notice sp-saved" role="status"><strong>已记录 ${checkinMinutes} 分钟 · 负荷${checkinLoad}</strong><p>${esc(checkinNote||'完成一次口语练习。')}</p></div><p>录音已保存；学习打卡单独记录。本稿仅演示状态。</p><div class="sp-stack">${action('回口语目录','return',true)}${action('查看历史录音','history')}</div>`:`<p class="sp-secondary">录音已保存。确认本次学习时间，再写下一个卡点即可。</p><form class="simple-form" id="sp-checkin-form"><label for="sp-minutes">实际学习时间（分钟）</label><input id="sp-minutes" name="minutes" type="number" value="${checkinMinutes}" required min="1" max="240" inputmode="numeric"/><fieldset class="sp-load"><legend>今天的负荷</legend>${['轻','刚好','重'].map(x=>`<label><input type="radio" name="sp-load" value="${x}" ${x===checkinLoad?'checked':''}/><span>${x}</span></label>`).join('')}</fieldset><label for="sp-note">记一个收获或卡点（可选）</label><textarea id="sp-note" name="note" rows="3" maxlength="1000" placeholder="例如：下次在长句后留一点停顿。">${esc(checkinNote)}</textarea>${s==='checkin-error'?'<div class="notice error" role="alert"><strong>学习打卡未保存</strong><p>录音已保存。分钟、负荷与手记保留，重试只提交本次打卡。</p></div>':''}<div class="sp-stack">${action(s==='checkin-error'?'重试保存收获':'保存收获','save-checkin',true)}${action('暂不记录，返回目录','return')}</div></form>`}</section>`;
  }
  speakingContent = function () {
    const s=normalizedState();
    const t=task();
    return `<div class="sp-shell">${toolbar()}${noThemeHead(`${t.label} · ${t.title}`,'先组织思路，再开口。')}<div class="sp-steps" aria-label="口语流程"><span class="${['default','prep','recording','permission','unsupported'].includes(s)?'current':''}">1 准备与录音</span><span class="${audioStates.has(s)||savedStates.has(s)&&s!=='checkin'&&s!=='checkin-saved'?'current':''}">2 回听与自评</span><span class="${s.startsWith('checkin')?'current':''}">3 记录收获</span></div>${s.startsWith('checkin')?checkinPanel(s):`<div class="sp-workspace">${material(t)}${recordPanel(t,s)}</div>`}<div class="sp-footnote">计时、播放器与文件操作为合成演示。本稿不会申请麦克风或生成下载。正式实现保留录音开始时间，未启用 AI 自动评分。</div>${s==='discard'?discardModal():''}</div>`;
  };
  function catalogContent() {
    return `<div class="sp-catalog">${header('口语练习','选一项专项，完成准备、录音与回听。','练习')}<div class="sp-catalog-toolbar"><div class="segmented"><button data-page="practice">听力与阅读</button><button class="selected" aria-pressed="true">口语表达</button></div>${action('我的历史录音','history')}</div><p class="sp-secondary">5 类原创专项 · 自评练习，不换算正式成绩。</p><div class="sp-task-grid">${tasks.map((t,i)=>`<article class="sp-task panel"><div class="sp-task-index">0${i+1} · ${esc(t.label)}</div><h2>${esc(t.title)}</h2><p>${esc(t.summary)}</p><div class="sp-task-times"><span>准备 <strong>${t.prep} 秒</strong></span><span>回答 <strong>${t.answer} 秒</strong></span></div>${action('开始练习 →','open-task',false,`data-speaking-task="${t.id}" aria-label="开始${t.label}，${esc(t.title)}"`)}</article>`).join('')}</div><div class="note">简短问答与资料回答按当前题库保留单题专项；完整三题组另有规则，不把单题练习冒充正式考试。</div><section class="sp-recent panel"><div class="sp-sectionhead"><h2>最近录音</h2>${action('查看全部','history')}</div><div class="sp-history-row"><div><strong>图片描述 · 一次小组会议</strong><p>10 月 13 日 19:42 · 28 秒 · 本机录音</p></div>${action('回听','open-history',false,'data-speaking-history="speaking-picture-01"')}</div></section><div class="sp-footnote">目录沿用当前 5 个真实任务与时长。录音条目为合成示例，不读取真实学习数据。</div></div>`;
  }
  function historyContent() {
    return `<div class="sp-history">${header('我的口语录音','按练习发生时间查看；保存与同步状态分别说明。','练习')}${action('← 返回口语目录','return')}<section class="panel sp-history-panel">${state==='empty'?`<div class="empty"><h2>还没有录音</h2><p>先完成一次专项练习，留住自己的起点。</p>${action('选择口语任务','return',true)}</div>`:`<div class="sp-sectionhead"><h2>2 段录音</h2><span>合成示例</span></div>${[{id:'speaking-picture-01',time:'10 月 13 日 19:42',duration:'28 秒',status:'本机录音'},{id:'speaking-read-01',time:'10 月 12 日 20:10',duration:'45 秒',status:'已同步 · 网页'}].map(r=>`<div class="sp-history-row"><div><strong>${esc(tasks.find(t=>t.id===r.id).label)} · ${esc(tasks.find(t=>t.id===r.id).title)}</strong><p>${r.time} · ${r.duration} · ${r.status}</p></div>${action('回听','open-history',false,`data-speaking-history="${r.id}"`)}</div>`).join('')}`}</section>${state==='loading'?'<div class="notice" role="status">正在读取这段录音… 已有记录与发生时间保持。</div>':''}${state==='missing'?`<div class="notice error" role="alert"><strong>暂时无法读取录音</strong><p>找不到本机音频，也没有已确认的云端副本。原条目与发生时间保留。</p>${action('重新读取','retry-history',true)}</div>`:''}${state==='playing'?`<section class="panel sp-history-player"><h2>${esc(tasks.find(t=>t.id===selectedHistory)?.title||'一次小组会议')}</h2>${player('历史录音',true)}${action('关闭回听','close-history')}</section>`:''}<div class="sp-footnote">沿用现有 RecordingList 与 recordingUrl 读取路径。本机保存成功与网页云同步互相区分；原生 App 不新增账号同步。</div></div>`;
  }
  pages.speakinglist='口语任务目录';
  pages.speakinghistory='历史录音';
  stateOptions.speakinglist=[['default','5 类口语任务']];
  stateOptions.speakinghistory=[['default','录音列表'],['playing','回听'],['loading','读取中'],['missing','读取失败'],['empty','暂无录音']];
  stateOptions.speaking=[['default','录音前 · 当前任务'],['picture','录音前 · 题图'],['respond','录音前 · 简短问答'],['information','录音前 · 资料'],['opinion','录音前 · 观点'],['prep','准备中'],['recording','录音中'],['processing','整理录音'],['saving','保存中可回听'],['saved','已保存 · 回听自评'],['self','勾选自评'],['save-error','保存失败 · 可回听下载'],['discard','未保存退出确认'],['exit-recording','录音中返回 · 停录整理'],['exit-saving','保存中返回 · 等待'],['interrupted','中断且未保存'],['permission','权限被拒绝'],['unsupported','设备不支持'],['checkin','记录收获'],['checkin-error','收获保存失败'],['checkin-saved','收获已记录']];
  window.designExtras=window.designExtras||{};
  window.designExtras.speakinglist=catalogContent;
  window.designExtras.speakinghistory=historyContent;
  window.speakingV11={tasks:tasks.map(t=>({id:t.id,type:t.type,prep:t.prep,answer:t.answer})),requestClose:requestClose};
  function beginSaving(fromExit=false) {
    clearTimeout(saveTimer);
    setState(fromExit?'exit-recording':'processing');
    saveTimer=setTimeout(()=>{
      if(page!=='speaking')return;
      setState(fromExit?'exit-saving':'saving');
      saveTimer=setTimeout(()=>{if(page==='speaking')setState('saved');},1100);
    },650);
  }
  function requestClose(target='speakinglist') {
    const s=normalizedState();
    returnTarget=target;
    if(s==='prep') {
      requestReturn=false;
      setState('default','[data-speaking-action="prepare"]');
      toast('准备已取消。再次返回可离开口语。');
      return;
    }
    if(s==='recording') {
      requestReturn=true;
      beginSaving(true);
      toast('录音已结束，整理和保存完成前留在本页。');
      return;
    }
    if(['processing','saving','exit-recording','exit-saving'].includes(s)) {
      requestReturn=true;
      if(['saving','exit-saving'].includes(s))setState('exit-saving');
      toast('正在整理或保存，请稍候。完成后再返回。');
      return;
    }
    if(['save-error','discard','interrupted'].includes(s)) {
      requestReturn=true;
      setState('discard','[data-speaking-action="stay"]');
      return;
    }
    requestReturn=false;
    clearTimeout(saveTimer);
    navigate(target);
    if(target==='speakinglist')window.scrollTo(0,catalogScroll);
  }
  document.addEventListener('click',e=>{
    const control=e.target.closest('[data-speaking-action]');
    if(control) {
      e.preventDefault();e.stopImmediatePropagation();
      if(control.disabled)return;
      const id=control.dataset.speakingAction;
      switch(id) {
        case 'open-task': catalogScroll=window.scrollY;taskId=control.dataset.speakingTask;checks=new Set();playing=false;sampleOpen=false;downloaded=false;requestReturn=false;navigate('speaking','default');break;
        case 'return':if(page==='speaking')requestClose();else{navigate('speakinglist');window.scrollTo(0,catalogScroll);}break;
        case 'history':if(page==='speaking')requestClose('speakinghistory');else navigate('speakinghistory');break;
        case 'prepare':checks=new Set();playing=false;sampleOpen=false;samplePlaying=false;downloaded=false;setState('prep','[data-speaking-action="record"]');break;
        case 'cancel-prep':setState('default','[data-speaking-action="prepare"]');break;
        case 'record':setState('recording','[data-speaking-action="stop"]');break;
        case 'stop':beginSaving();break;
        case 'play':playing=!playing;render();document.querySelector('[data-speaking-action="play"]')?.focus({preventScroll:true});break;
        case 'sample-audio':samplePlaying=!samplePlaying;sampleOpen=true;render();document.querySelector('[data-speaking-action="sample-audio"]')?.focus({preventScroll:true});break;
        case 'retry':clearTimeout(saveTimer);setState('saving');saveTimer=setTimeout(()=>{if(page==='speaking')setState('saved');},1100);break;
        case 'download':downloaded=true;render();if(state==='discard')document.querySelector('[data-speaking-action="download"]')?.focus({preventScroll:true});toast('设计演示：保留下载入口；本原型不生成文件。');break;
        case 'discard':setState('discard','[data-speaking-action="stay"]');break;
        case 'stay':setState('save-error','[data-speaking-action="retry"]');break;
        case 'confirm-discard':checks=new Set();playing=false;downloaded=false;clearTimeout(saveTimer);navigate(returnTarget);break;
        case 'rerecord':if(savedStates.has(normalizedState())){checks=new Set();playing=false;sampleOpen=false;setState('prep');}break;
        case 'checkin':if(savedStates.has(normalizedState())){checkinMinutes=Math.max(1,Math.ceil((Math.min(task().answer,28)+task().prep)/60));checkinNote='';checkinLoad='刚好';setState('checkin','[id="sp-minutes"]');}break;
        case 'save-checkin':{const form=document.getElementById('sp-checkin-form');if(!form?.reportValidity())return;checkinMinutes=Number(document.getElementById('sp-minutes').value);checkinLoad=form.querySelector('input[name="sp-load"]:checked')?.value||'刚好';checkinNote=document.getElementById('sp-note').value;setState('checkin-saved');break;}
        case 'open-history':selectedHistory=control.dataset.speakingHistory;historyPlaying=false;navigate('speakinghistory','playing');break;
        case 'history-play':historyPlaying=!historyPlaying;render();document.querySelector('[data-speaking-action="history-play"]')?.focus({preventScroll:true});break;
        case 'close-history':historyPlaying=false;setState('default');break;
        case 'retry-history':setState('loading');saveTimer=setTimeout(()=>{if(page==='speakinghistory')setState('playing');},800);break;
      }
      return;
    }
    if(page==='speaking'&&e.target.closest('[data-page],a[href]')) {
      const link=e.target.closest('[data-page],a[href]');
      e.preventDefault();e.stopImmediatePropagation();
      requestClose(link.dataset.page||'speakinglist');
    }
  },{capture:true});
  document.addEventListener('change',e=>{
    if(e.target.matches('[data-speaking-check]')) {
      const n=Number(e.target.dataset.speakingCheck);
      if(e.target.checked)checks.add(n);else checks.delete(n);
      return;
    }
    if(e.target.name==='sp-load')checkinLoad=e.target.value;
    if(page==='speaking'&&e.target.id==='page-control') {
      const next=e.target.value;
      e.stopImmediatePropagation();
      e.target.value='speaking';
      requestClose(next);
    }
    if(page==='speaking'&&e.target.id==='state-control')clearTimeout(saveTimer);
  },{capture:true});
  document.addEventListener('input',e=>{
    if(e.target.id==='sp-note')checkinNote=e.target.value;
    if(e.target.id==='sp-minutes')checkinMinutes=Number(e.target.value);
  },{capture:true});
  document.addEventListener('toggle',e=>{
    if(e.target.matches('.sp-sample'))sampleOpen=e.target.open;
  },{capture:true});
  document.addEventListener('keydown',e=>{
    if(page!=='speaking')return;
    if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();e.stopImmediatePropagation();return;}
    if(e.key==='Escape') {
      e.preventDefault();e.stopImmediatePropagation();
      if(state==='discard')setState('save-error','[data-speaking-action="retry"]');else requestClose();
    }
    if(e.key==='Tab'&&state==='discard') {
      const controls=[...document.querySelectorAll('.sp-dialog button:not(:disabled)')];
      if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();e.stopImmediatePropagation();controls.at(-1)?.focus();}
      else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();e.stopImmediatePropagation();controls[0]?.focus();}
    }
  },{capture:true});
  // Synthetic self-check fixture stays distinct from persisted Recording metadata.
  if(state==='self')checks.add(0);
})();
